import java.io.*;
import java.util.*;

public class Main {
    static class Reader {
        private DataInputStream din;
        private byte[] buffer;
        private int ptr, len;
        private static final int SIZE = 1 << 15;

        Reader() {
            din = new DataInputStream(System.in);
            buffer = new byte[SIZE];
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = din.read(buffer, 0, SIZE);
                ptr = 0;
                if (len == -1) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            int ret = 0;
            while (c >= '0' && c <= '9') {
                ret = ret * 10 + c - '0';
                c = read();
            }
            return neg ? -ret : ret;
        }
    }

    static boolean get(int w, int m) {
        int[] stack = new int[1024];
        int size = 0;
        stack[size++] = m;
        while (size > 0) {
            int x = stack[--size];
            if (x == 0) return true;
            if (x % w != 0) continue;
            x /= w;
            if (x == 1) return true;
            if (size + 3 > stack.length) {
                stack = Arrays.copyOf(stack, stack.length * 2);
            }
            stack[size++] = x + 1;
            stack[size++] = x - 1;
            stack[size++] = x;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        Reader in = new Reader();
        int w = in.nextInt();
        int m = in.nextInt();
        boolean ans = get(w, m) || get(w, m - 1) || get(w, m + 1);
        System.out.println(ans ? "YES" : "NO");
    }
}
